using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using TasiaCraft;
public static partial class MediaBinTest {
 static void RejectBatch(Action action,string label){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}catch(InvalidOperationException){rejected=true;}catch(FileNotFoundException){rejected=true;}catch(InvalidDataException){rejected=true;}Check(rejected,label);}
 static byte[] BatchPixels(LivePreview preview,Project p,double time){preview.SetProject(p);preview.SetSelection(null);preview.Seek(time);preview.UpdateLayout();var bitmap=new RenderTargetBitmap(p.Width,p.Height,96,96,PixelFormats.Pbgra32);bitmap.Render(preview.Stage);var data=new byte[p.Width*p.Height*4];bitmap.CopyPixels(data,p.Width*4,0);return data;}
 static void BatchTests(Editor editor,Project original,LivePreview preview){
  var p=new Project{Width=640,Height=480,TrackCount=2};p.Media.Add(Clone(original).Media[0]);p.Media.Add(Clone(original).Media[2]);p.Media.Add(Clone(original).Media.Last());p.Media[0].Name="Z-red";p.Media[1].Name="A-blue";p.Media[2].Name="M-audio";string baseline=json.Serialize(p);
  var plan=MediaBatchInsertion.Plan(p,p.Media,.25,1);Check(plan.Count==3&&plan.Select(c=>c.MediaId).SequenceEqual(p.Media.Select(m=>m.Id)),"batch planner retains supplied source order");Check(plan[0].Start==.25&&plan[1].Start==5.25&&plan[2].Start==10.25,"image and audio clips are consecutive from insertion time");Check(plan[0].Duration==5&&plan[1].Duration==5&&plan[2].Duration==p.Media[2].Duration,"images use five seconds and audio retains source duration");Check(plan.All(c=>c.Track==1&&c.NativeSize&&c.In==0&&c.Scale==1)&&plan.Select(c=>c.Id).Distinct().Count()==3,"batch clips have independent identities and native transforms");Check(MediaBatchInsertion.Plan(p,new[]{p.Media[0],p.Media[0]},0,0).Count==1,"repeated selection entry is inserted once");Check(MediaBatchInsertion.Plan(p,new TasiaCraft.Media[0],0,0).Count==0,"empty batch plan is valid");Check(json.Serialize(p)==baseline,"batch planning never mutates project metadata");
  RejectBatch(()=>MediaBatchInsertion.Plan(null,p.Media,0,0),"null insertion project rejected");RejectBatch(()=>MediaBatchInsertion.Plan(p,null,0,0),"null insertion selection rejected");RejectBatch(()=>MediaBatchInsertion.Plan(p,new[]{new TasiaCraft.Media{Id=p.Media[0].Id,Path=p.Media[0].Path}},0,0),"stale media with matching ID rejected");RejectBatch(()=>MediaBatchInsertion.Plan(p,new TasiaCraft.Media[]{p.Media[0],null},0,0),"null batch member rejected atomically");RejectBatch(()=>MediaBatchInsertion.Plan(p,p.Media,double.NaN,0),"NaN insertion time rejected");RejectBatch(()=>MediaBatchInsertion.Plan(p,p.Media,double.PositiveInfinity,0),"infinite insertion time rejected");RejectBatch(()=>MediaBatchInsertion.Plan(p,p.Media,-1,0),"negative insertion time rejected");RejectBatch(()=>MediaBatchInsertion.Plan(p,p.Media,86395,0),"whole batch crossing 24-hour endpoint rejected");RejectBatch(()=>MediaBatchInsertion.Plan(p,p.Media,0,2),"out-of-range target track rejected");p.LockedTracks.Add(0);RejectBatch(()=>MediaBatchInsertion.Plan(p,p.Media,0,0),"locked target track rejected");p.LockedTracks.Clear();string saved=p.Media[1].Path;p.Media[1].Path=Path.Combine(root,"absent-batch.png");RejectBatch(()=>MediaBatchInsertion.Plan(p,p.Media,0,0),"missing later source rejects the entire batch");p.Media[1].Path=saved;double duration=p.Media[2].Duration;p.Media[2].Duration=0;RejectBatch(()=>MediaBatchInsertion.Plan(p,p.Media,0,0),"invalid later source duration rejects the entire batch");p.Media[2].Duration=duration;int width=p.Media[1].Width;p.Media[1].Width=0;RejectBatch(()=>MediaBatchInsertion.Plan(p,p.Media,0,0),"unknown visual dimensions rejected before insertion");p.Media[1].Width=width;Check(json.Serialize(p)==baseline,"rejected plans leave original project unchanged");
  Reset(editor,p);Set(editor,"projectConfigured",false);Set(editor,"mediaSort","Name");Set(editor,"mediaDescending",false);Call(editor,"Panel","Media");ChooseBin(editor,p.Media[0].Id,p.Media[1].Id);var bin=(ListBox)Field(editor,"bin");var insert=bin.ContextMenu.Items.OfType<MenuItem>().First(i=>(string)i.Header=="Add to Timeline at Playhead");Call(editor,"Seek",0.0);insert.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));var inserted=P(editor);Check(inserted.Clips.Count==2&&inserted.Clips[0].MediaId==p.Media[1].Id&&inserted.Clips[1].MediaId==p.Media[0].Id,"actual context action inserts selected entries in visible sorted order");Check(inserted.Clips[0].Start==0&&inserted.Clips[1].Start==5&&inserted.Clips.All(c=>c.Track==0),"context batch is adjacent on first track at unchanged head");Check((double)Field(editor,"head")==0&&Undos(editor)==1&&(bool)Field(editor,"dirty"),"context batch has one checkpoint and leaves playhead unchanged");Check(Selected(editor).Count==2&&Field(editor,"openedGroupId")==null,"all inserted clips selected on Main Timeline");Check(inserted.Width==320&&inserted.Height==180,"empty unconfigured project uses first visual source dimensions");string after=json.Serialize(inserted);var blue=BatchPixels(preview,inserted,1);var red=BatchPixels(preview,inserted,6);int center=(90*320+160)*4;Check(blue[center]>200&&blue[center+2]<30&&red[center+2]>200&&red[center]<30,"actual preview shows blue then red without stretching");string video=Path.Combine(root,"batch.mp4"),rgb=Path.Combine(root,"batch-red.rgb");Engine.Render(inserted,video,null);Engine.Run("ffmpeg","-y -v error -ss 6 -i "+Engine.Quote(video)+" -frames:v 1 -pix_fmt rgb24 -f rawvideo "+Engine.Quote(rgb));byte[] decoded=File.ReadAllBytes(rgb);Check(decoded[(90*320+160)*3]>200&&decoded[(90*320+160)*3+2]<30,"decoded sequence export agrees with second source preview");string file=Path.Combine(root,"batch.tasiaproj");Engine.Save(inserted,file);Check(json.Serialize(Engine.Load(file))==after,"batch save/reopen preserves exact sources clips and dimensions");Call(editor,"Undo");Check(json.Serialize(P(editor))==baseline,"one undo restores empty timeline and original dimensions");Call(editor,"Redo");Check(json.Serialize(P(editor))==after,"one redo restores complete batch exactly");
  Reset(editor,p);Set(editor,"projectConfigured",true);Set(editor,"mediaDescending",true);Call(editor,"Panel","Media");ChooseBin(editor,p.Media[0].Id,p.Media[1].Id);Call(editor,"InsertBinMedia");Check(P(editor).Clips.Select(c=>c.MediaId).SequenceEqual(new[]{p.Media[0].Id,p.Media[1].Id}),"descending bin order controls batch source order");Check(P(editor).Width==640&&P(editor).Height==480,"configured project dimensions retained");
  Reset(editor,p);ChooseBin(editor,p.Media[0].Id,p.Media[1].Id);Set(editor,"busy",true);Call(editor,"InsertBinMedia");Check(json.Serialize(P(editor))==baseline&&Undos(editor)==0,"busy batch insertion makes no changes");Set(editor,"busy",false);ChooseBin(editor);Call(editor,"InsertBinMedia");Check(json.Serialize(P(editor))==baseline&&Undos(editor)==0,"empty context batch makes no checkpoint");ChooseBin(editor,p.Media[0].Id,p.Media[1].Id);saved=P(editor).Media[1].Path;P(editor).Media[1].Path=Path.Combine(root,"absent-ui-batch.png");string missing=json.Serialize(P(editor));Call(editor,"InsertBinMedia");Check(json.Serialize(P(editor))==missing&&Undos(editor)==0&&!(bool)Field(editor,"dirty"),"actual insertion failure is atomic and creates no checkpoint");P(editor).Media[1].Path=saved;
  Reset(editor,original);Set(editor,"mediaFilter","All media");Set(editor,"mediaSort","Type");Set(editor,"mediaDescending",false);Call(editor,"Panel","Media");ChooseBin(editor,original.Media[0].Id,original.Media[2].Id);string oldClips=json.Serialize(P(editor).Clips),oldGroups=json.Serialize(P(editor).Groups);Set(editor,"openedGroupId",P(editor).Groups[0].Id);Call(editor,"InsertBinMedia");Check(P(editor).Clips.Count==original.Clips.Count+2&&json.Serialize(P(editor).Clips.Take(original.Clips.Count).ToList())==oldClips,"batch overlap preserves all existing clips and their timing");Check(json.Serialize(P(editor).Groups)==oldGroups&&Field(editor,"openedGroupId")==null,"batch preserves groups and returns to Main Timeline");Call(editor,"Undo");Check(json.Serialize(P(editor))==json.Serialize(original),"one undo removes only inserted batch from existing project");Set(editor,"projectConfigured",false);Reset(editor,original);
 }
}
